async function getEmployeeData(employeeId) {
  try {
    const response = await fetch(`/api/employees/${employeeId}`);
    if (!response.ok) {
      throw new Error('Failed to fetch employee data');
    }
    const data = await response.json();
    return data;
  } catch (error) {
    console.error('Error:', error);
    throw error;
  }
}

